import sys, json

# The operator's export occupant: the trigger for an export, from the OS side.
#
# It owns no format and holds no dump. What leaves here is an ADDRESS on the
# `export` lane, carrying `hop.target`; the level below re-stamps it onto the
# lane the memory accepts -- `{route: 'in_export', target: <member path>}` --
# and relays it unchanged from there. The file is written where the memory is;
# only the ASKING is the operator's.
#
# Since GH #555 the request may carry a second address, and it is passed through
# exactly like the first: `export_to` names the DIRECTORY of one run, relative
# to the fence each holder's store declares for itself
# (`params.transfer.base_path`). Under it every holder keeps a directory of its
# own name, so two hives that both have a table called `entities` never meet.
# Absent, each holder writes into its own name directly. This cell does not
# resolve it, does not check it and never sees the file: a path this side
# canonicalised would be a claim about a filesystem the operator does not
# stand on.

doc = json.load(sys.stdin)
env = doc["envelope"]
hop = (env.get("header") or {}).get("hop") or {}
body = doc["body"]

CALL_ID = str(hop.get("tool_call_id") or "")


def receipt(text, code="", extra=None):
    header = {"route": "receipt", "operation": "operator_export"}
    if code:
        header["error_code"] = code
    if CALL_ID:
        header["tool_call_id"] = CALL_ID
    header.update(extra or {})
    sys.stdout.write(json.dumps({
        "header": header,
        "messages": [{"origin": "tool", "type": "tool_result", "id": CALL_ID,
                      "text": text}]}))
    sys.exit(0)


def args_of(d):
    """The request, out of the last `tool_call` turn, or off the hop."""
    raw = ""
    for m in (d.get("messages") or []):
        if m.get("type") == "tool_call" and m.get("text"):
            raw = m["text"]
    try:
        v = json.loads(raw)
    except Exception:
        v = None
    return v if isinstance(v, dict) else {}


# ---- What came back from below. It is rendered rather than forwarded: an
# operator asked a question and is owed a sentence, not a lane.
if str(hop.get("route") or "") == "export_done":
    said = ""
    for m in (body.get("messages") or []):
        if m.get("text"):
            said = str(m["text"])
    code = str(hop.get("error_code") or "")
    extra = {}
    for key in ("target", "part", "parts", "export_hive", "seed_dir"):
        if hop.get(key) is not None:
            extra[key] = hop[key]
    if code:
        text = "the export was refused: %s" % code
        if said:
            text += " -- " + said[:600]
    else:
        text = said or "the export answered without a sentence"
    receipt(text, code, extra)

# ---- The trigger.
args = args_of(body)
target = str(args.get("target") or hop.get("target") or "")
if not target:
    # Fail loudly rather than broadcast. An export with no address would be a
    # request every memory in the colony could believe was meant for it.
    receipt("in_dump needs a target: the path of the member whose memory is "
            "to be exported", "export_target_missing")

header = {"route": "export", "operation": "operator_export",
          "target": target}
if CALL_ID:
    header["tool_call_id"] = CALL_ID
for key in ("since", "export_to"):
    if args.get(key) is not None:
        header[key] = args[key]
sys.stdout.write(json.dumps({"header": header, "messages": []}))
